def total_par_produit(ventes):
    totaux = {}
    for v in ventes:
        totaux[v['produit']] = totaux.get(v['produit'], 0) + v['montant']
    return totaux

mediane <- function(v) {
  w <- sort(v)
  n <- length(w)
  if (n %% 2 == 1) {
    w[(n + 1) / 2]
  } else {
    (w[n / 2] + w[n / 2 + 1]) / 2
  }
}

def statistiques(valeurs):
    tri = sorted(valeurs)
    n = len(tri)
    if n % 2 == 1:
        med = tri[n // 2]
    else:
        med = (tri[n // 2 - 1] + tri[n // 2]) / 2
    return {'moyenne': sum(valeurs) / n, 'mediane': med}
